begin;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.actor(n integer) returns uuid language sql immutable as $$select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.failure(statement text) returns text language plpgsql as $$begin execute statement;return 'OK';exception when others then return case when sqlstate='P0001' then sqlerrm else sqlstate end;end$$;
create temp table cases(name text primary key,value jsonb);
grant all on cases to authenticated,service_role;
create function pg_temp.put(name text,value jsonb) returns void language sql as $$insert into cases values(name,value) on conflict(name) do update set value=excluded.value$$;
create function pg_temp.get(name text) returns jsonb language sql stable as $$select value from cases where cases.name=$1$$;
create function pg_temp.submit(n integer,key text,ref text,method text default 'easypaisa',offer text default 'synthetic') returns jsonb language sql as $$
 select public.qiyadat_payment_submit(pg_temp.actor(n),jsonb_build_object('offer_code',offer,'payment_method',method,'transaction_hash',encode(extensions.digest(ref,'sha256'),'hex')),
 key,decode('01'||repeat('00',29),'hex'),encode(extensions.digest(ref,'sha256'),'hex'),'********test')$$;
insert into auth.users(id,email) select pg_temp.actor(n),'phase6-'||n||'@example.invalid' from generate_series(701,710)n;
insert into public.payment_offers(code,name,amount_minor,accepted_methods,instructions,active,benefits)
values('synthetic','Synthetic access',123456,array['easypaisa','jazzcash']::public.payment_method[],'Synthetic instructions',true,
 '{"additional_20_word_sessions":true,"session_access":"during_entitlement","reports_per_rolling_window":3,"report_window_hours":24,"saved_history_and_progress":true}');
select ok(not has_function_privilege('authenticated','public.qiyadat_payment_submit(uuid,jsonb,text,bytea,text,text)','EXECUTE'),'Candidate cannot call trusted submission');
select ok(not has_function_privilege('anon','public.qiyadat_payment_offers()','EXECUTE'),'Public offers only through API');
select ok(has_function_privilege('authenticated','public.qiyadat_payment_history(jsonb,integer)','EXECUTE'),'Candidate history allowed');
select ok(not has_column_privilege('authenticated','public.payment_submissions','transaction_id_ciphertext','SELECT'),'Ciphertext hidden');
select ok(not has_column_privilege('authenticated','public.payment_submissions','transaction_id_hash','SELECT'),'Hash hidden');
select ok(not has_column_privilege('authenticated','public.payment_submissions','verification_note','SELECT'),'Note hidden');
select is(pg_temp.failure($$update payment_offers set benefits='{}'$$),'23514','Invalid benefits rejected');
select is(pg_temp.failure($$update payment_offers set benefits=null$$),'23514','Active offers require benefits');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(pg_temp.failure($$select public.qiyadat_payment_offers()$$),'FEATURE_DISABLED','Payments disabled by seed');
select is(pg_temp.failure($$select pg_temp.submit(701,'synthetic-key-001','synthetic-one')$$),'FEATURE_DISABLED','Disabled submission');
update public.app_settings set value='true' where key='payments_enabled';
select is(public.qiyadat_payment_offers()#>>'{0,amount_minor}','123456','Offer price from reviewed configuration');
select is(jsonb_array_length(public.qiyadat_payment_offers()),1,'Active offer');
update public.payment_offers set active=false;
select is(public.qiyadat_payment_offers(),'[]'::jsonb,'No active offer has no fallback');
update public.payment_offers set active=true,valid_from=now()+interval '1 day';
select is(public.qiyadat_payment_offers(),'[]'::jsonb,'Future offer excluded');
update public.payment_offers set valid_from=now()-interval '2 days',valid_until=now()-interval '1 day';
select is(public.qiyadat_payment_offers(),'[]'::jsonb,'Expired offer excluded');
select is(pg_temp.submit(701,'synthetic-key-001','synthetic-one')->>'error_code','PAYMENT_OFFER_INACTIVE','Expired submit rejected');
update public.payment_offers set valid_until=null;
select is(pg_temp.submit(701,'synthetic-key-001','synthetic-one','bank_transfer')->>'error_code','VALIDATION_ERROR','Unaccepted method rejected');
select pg_temp.put('submitted',pg_temp.submit(701,'synthetic-key-001','synthetic-one'));
select is(pg_temp.get('submitted')->>'status','201','Submission created');
select is(pg_temp.get('submitted')#>>'{body,data,status}','pending','Pending state');
select is(pg_temp.get('submitted')#>'{body,data,decision}','null'::jsonb,'No decision');
select is((select count(*)::integer from public.entitlements),0,'Submission grants no entitlement');
select is((select amount_minor::integer from public.payment_submissions where user_id=pg_temp.actor(701)),123456,'Price snapshot');
select is(pg_temp.submit(701,'synthetic-key-001','synthetic-one'),pg_temp.get('submitted'),'Exact replay');
select is(pg_temp.failure($$select pg_temp.submit(701,'synthetic-key-001','synthetic-other')$$),'IDEMPOTENCY_CONFLICT','Different input conflicts');
select is(pg_temp.submit(701,'synthetic-key-002','synthetic-other')->>'error_code','PAYMENT_PENDING_EXISTS','One pending');
select is(pg_temp.submit(702,'synthetic-key-001','synthetic-one')->>'error_code','TRANSACTION_ID_EXISTS','Provider hash globally unique');
select is(pg_temp.submit(702,'synthetic-key-002','synthetic-one','jazzcash')->>'status','201','Same reference different provider');
select is(pg_temp.failure($$select pg_temp.submit(703,'short','synthetic-other')$$),'VALIDATION_ERROR','Invalid idempotency');
select is((select count(*)::integer from public.api_idempotency_keys where user_id=pg_temp.actor(701)),1,'Failed mutations do not retain keys');
select ok((select expires_at>=created_at+interval '24 hours' from public.api_idempotency_keys where user_id=pg_temp.actor(701)),'Minimum key retention');
select is(private.payment_transaction_hash('easypaisa',U&'  cafe\0301  '),encode(extensions.digest(U&'caf\00e9','sha256'),'hex'),'NFC trim hash contract');
select isnt(private.payment_transaction_hash('easypaisa','A-B'),private.payment_transaction_hash('easypaisa','AB'),'Separators significant');
select isnt(private.payment_transaction_hash('easypaisa','AB'),private.payment_transaction_hash('easypaisa','ab'),'Case significant');
update public.app_settings set value=jsonb_set(value,'{payment_submit}','1') where key='api_rate_limits';
select is(pg_temp.submit(704,'synthetic-limit-1','synthetic-one')->>'error_code','TRANSACTION_ID_EXISTS','Failed valid attempt counted');
select is(pg_temp.failure($$select pg_temp.submit(704,'synthetic-limit-2','synthetic-new')$$),'RATE_LIMITED','Endpoint limit');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000701"}',true);
set local role authenticated;
select is(jsonb_array_length(public.qiyadat_payment_history()),1,'Own history');
select is(public.qiyadat_payment_history()#>>'{0,id}',pg_temp.get('submitted')#>>'{body,data,id}','History ownership');
select ok(not (public.qiyadat_payment_history()->0 ?| array['transaction_id','transaction_id_hash','transaction_id_ciphertext','verification_note','decided_by']),'History projection hides sensitive columns');
select is(pg_temp.failure($$select public.qiyadat_payment_history(null,101)$$),'VALIDATION_ERROR','Limit cap');
select is(pg_temp.failure($$select public.qiyadat_payment_submit(null,'{}',null,null,null,null)$$),'42501','Browser mutation execution denied');
reset role;
select * from finish();
rollback;
